+package com.example;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.example.views.AboutView;
+import com.example.views.ContactView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.textfield.TextField;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void sendAndGuard() {
+        navigate(ContactView.class);
+        test($(Button.class).withText("Send").single()).click();
+        assertTrue($(TextField.class).withCaption("Name").single().isInvalid());
+        $(TextField.class).withCaption("Name").single().setValue("A");
+        $(TextField.class).withCaption("Phone").single().setValue("1");
+        $(com.vaadin.flow.component.textfield.TextArea.class).single().setValue("hi");
+        test($(Button.class).withText("Send").single()).click();
+        assertFalse($(Button.class).withText("Send").single().isEnabled());
+        $(TextField.class).withCaption("Name").single().setValue("B");
+        assertTrue($(Button.class).withText("Send").single().isEnabled());
+        $(TextField.class).withCaption("Name").single().clear();
+        navigate(AboutView.class);
+        assertEquals(0, $(Dialog.class).all().size());
+    }
+}
